### 要点
- 前缀和：prefix[i] 表示原数组 [0, i) 的元素之和
- 差分数组：diff[i] = nums[i] - nums[i-1]
- 前缀和常配合 HashMap 使用（和为K的子数组）
- 差分数组适用于频繁对区间进行加减操作的场景

### 示例/代码
```java
// 前缀和 + HashMap：和为K的子数组 (LeetCode 560)
public int subarraySum(int[] nums, int k) {
    Map<Integer, Integer> map = new HashMap<>();
    map.put(0, 1);
    int count = 0, prefixSum = 0;
    for (int num : nums) {
        prefixSum += num;
        count += map.getOrDefault(prefixSum - k, 0);
        map.put(prefixSum, map.getOrDefault(prefixSum, 0) + 1);
    }
    return count;
}

// 差分数组模板
public class Difference {
    private int[] diff;
    public Difference(int[] nums) {
        diff = new int[nums.length];
        diff[0] = nums[0];
        for (int i = 1; i < nums.length; i++) diff[i] = nums[i] - nums[i-1];
    }

    public void increment(int left, int right, int val) {
        diff[left] += val;
        if (right + 1 < diff.length) diff[right + 1] -= val;
    }

    public int[] result() {
        int[] res = new int[diff.length];
        res[0] = diff[0];
        for (int i = 1; i < diff.length; i++) res[i] = res[i-1] + diff[i];
        return res;
    }
}
